using AfriWallet.Fraud.Signals.Domain.Enums;using AfriWallet.Fraud.Signals.Domain.Exceptions;using AfriWallet.Fraud.Signals.Domain.ValueObjects;
namespace AfriWallet.Fraud.Signals.Domain.Aggregates;
public sealed class FraudSignal
{
    private FraudSignal(Guid id,string eventId,FraudSignalSource source,FraudSignalType type,FraudSignalSeverity severity,FraudSubject subject,DateTimeOffset occurredAt,DateTimeOffset recordedAt,IReadOnlyDictionary<string,string> attributes){Id=id;EventId=eventId;Source=source;Type=type;Severity=severity;Subject=subject;OccurredAt=occurredAt;RecordedAt=recordedAt;Attributes=attributes;}
    public Guid Id{get;}public string EventId{get;}public FraudSignalSource Source{get;}public FraudSignalType Type{get;}public FraudSignalSeverity Severity{get;}public FraudSubject Subject{get;}public DateTimeOffset OccurredAt{get;}public DateTimeOffset RecordedAt{get;}public IReadOnlyDictionary<string,string> Attributes{get;}
    public static FraudSignal Create(string eventId,FraudSignalSource source,FraudSignalType type,FraudSignalSeverity severity,FraudSubject subject,DateTimeOffset occurredAt,DateTimeOffset recordedAt,IReadOnlyDictionary<string,string>? attributes=null){if(string.IsNullOrWhiteSpace(eventId))throw new FraudSignalDomainException("Event id is required.");if(!Enum.IsDefined(source)||!Enum.IsDefined(type)||!Enum.IsDefined(severity))throw new FraudSignalDomainException("Signal classification is invalid.");if(occurredAt>recordedAt.AddMinutes(5))throw new FraudSignalDomainException("Event occurrence time cannot be materially in the future.");var safe=attributes is null?new Dictionary<string,string>():new Dictionary<string,string>(attributes,StringComparer.OrdinalIgnoreCase);return new FraudSignal(Guid.NewGuid(),eventId.Trim(),source,type,severity,subject,occurredAt,recordedAt,safe);}
}